	/**
	* Creates a ES6 module with the whole style dictionary
	*
	* @memberof Formats
	* @kind member
	* @example
	* ```js
	* export default {
	*   "color": {
	*     "base": {
	*        "red": "#ff0000"
	*     }
	*   }
	* }
	* ```
	*/
	[javascriptEsm]: async function({ dictionary, file, options }) {
		const { formatting, minify = false, flat = false } = options;
		let { tokens } = dictionary;
		tokens = stripMetaProps(tokens, options);
		const header = await fileHeader({
			file,
			formatting: getFormattingCloneWithoutPrefix(formatting),
			options
		});
		let dictionaryString;
		if (flat) dictionaryString = JSON.stringify(Object.fromEntries(dictionary.allTokens.map((token) => [token.name, options.usesDtcg ? token.$value : token.value])), null, 2);
		else dictionaryString = JSON.stringify(minify ? minifyDictionary(tokens, options.usesDtcg) : tokens, null, 2);
		return formatJS(`${header}export default ${dictionaryString};\n`);
	},
